   575→        {
   576→            IIncomingTxFilter[] filters = _preHashFilters;
   577→            for (int i = 0; i < filters.Length; i++)
   578→            {
   579→                AcceptTxResult accepted = filters[i].Accept(tx, ref state, handlingOptions);
   580→
   581→                if (!accepted)
   582→                {
   583→                    tx.ClearPreHash();
   584→                    return accepted;
   585→                }
   586→            }
   587→
   588→            filters = _postHashFilters;
   589→            for (int i = 0; i < filters.Length; i++)
   590→            {
   591→                AcceptTxResult accepted = filters[i].Accept(tx, ref state, handlingOptions);
   592→
   593→                if (!accepted) return accepted;
   594→            }
   595→
   596→            return AcceptTxResult.Accepted;
