   599→        private AcceptTxResult AddCore(Transaction tx, ref TxFilteringState state, bool isPersistentBroadcast)
   600→        {
   601→            bool eip1559Enabled = _specProvider.GetCurrentHeadSpec().IsEip1559Enabled;
   602→            UInt256 effectiveGasPrice = tx.CalculateEffectiveGasPrice(eip1559Enabled, _headInfo.CurrentBaseFee);
   603→            TxDistinctSortedPool relevantPool = (tx.SupportsBlobs ? _blobTransactions : _transactions);
   604→
   605→            relevantPool.TryGetBucketsWorstValue(tx.SenderAddress!, out Transaction? worstTx);
   606→            tx.GasBottleneck = (worstTx is null || effectiveGasPrice <= worstTx.GasBottleneck)
   607→                ? effectiveGasPrice
   608→                : worstTx.GasBottleneck;
   609→
   610→            bool inserted = relevantPool.TryInsert(tx.Hash!, tx, out Transaction? removed);
   611→
   612→            if (!inserted)
   613→            {
   614→                // it means it failed on adding to the pool - it is possible when new tx has the same sender
   615→                // and nonce as already existent tx and is not good enough to replace it
   616→                Metrics.PendingTransactionsPassedFiltersButCannotReplace++;
   617→                return AcceptTxResult.ReplacementNotAllowed;
   618→            }
   619→
   620→            if (tx.Hash == removed?.Hash)
   621→            {
   622→                // it means it was added and immediately evicted - pool was full of better txs
   623→                if (!isPersistentBroadcast || tx.SupportsBlobs || !_broadcaster.Broadcast(tx, true))
   624→                {
   625→                    // we are adding only to persistent broadcast - not good enough for standard pool,
   626→                    // but can be good enough for TxBroadcaster pool - for local txs only
   627→                    Metrics.PendingTransactionsPassedFiltersButCannotCompeteOnFees++;
   628→                    return AcceptTxResult.FeeTooLowToCompete;
   629→                }
   630→                else
   631→                {
   632→                    return AcceptTxResult.Accepted;
   633→                }
   634→            }
   635→
   636→            relevantPool.UpdateGroup(tx.SenderAddress!, state.SenderAccount, _updateBucketAdded);
   637→            Interlocked.Increment(ref Metrics.PendingTransactionsAdded);
   638→            Interlocked.Increment(ref _pendingTransactionsAdded);
   639→            if (tx.Supports1559) { Metrics.Pending1559TransactionsAdded++; }
   640→            if (tx.SupportsBlobs) { Metrics.PendingBlobTransactionsAdded++; }
   641→
   642→            if (removed is not null)
   643→            {
   644→                RemovePendingDelegations(removed);
   645→                EvictedPending?.Invoke(this, new TxEventArgs(removed));
   646→                // transaction which was on last position in sorted TxPool and was deleted to give
   647→                // a place for a newly added tx (with higher priority) is now removed from hashCache
   648→                // to give it opportunity to come back to TxPool in the future, when fees drops
   649→                _hashCache.DeleteFromLongTerm(removed.Hash!);
   650→                Metrics.PendingTransactionsEvicted++;
   651→            }
   652→
   653→            AddPendingDelegations(tx);
   654→
   655→            _broadcaster.Broadcast(tx, isPersistentBroadcast);
